/*
 * m1_view.c - milestone M1 check: show real game graphics through the PC HAL.
 *
 * Reproduces the final state of the title screen (src/title_screen.c,
 * CB2_InitTitleScreen + Task_TitleScreenPhase2) with the game's own headers
 * and register macros: assets generated by the native tools are LZ77-
 * decompressed by bios_pc.c into VRAM at 0x06000000, then drawn by the
 * software PPU (gpu_pc.c) into an SDL window.
 *
 *   pem_m1_view [--root DIR] [--shot out.bmp]
 */
/* System headers first: the game's headers define macros (abs, min, max...)
 * that clash with them. */
#include <SDL.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "gpu_pc.h"
#include "hw_pc.h"
#include "platform_pc.h"

#include "global.h"   /* game headers: REG_*, BGCNT_*, DISPCNT_*, BG_CHAR_ADDR... */

static char s_root[1024] = ".";

static void *load_file(const char *rel, size_t *size_out) {
    char path[1200];
    snprintf(path, sizeof path, "%s/%s", s_root, rel);
    FILE *f = fopen(path, "rb");
    if (!f) pc_fatal("cannot open %s (run gen_assets.py first)", path);
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    void *buf = malloc((size_t)n + 4);
    if (!buf || fread(buf, 1, (size_t)n, f) != (size_t)n) pc_fatal("cannot read %s", path);
    fclose(f);
    if (size_out) *size_out = (size_t)n;
    return buf;
}

static void lz_to(const char *rel, uintptr_t dest) {
    void *data = load_file(rel, NULL);
    LZ77UnCompVram(data, (void *)dest);
    free(data);
}

static void setup_title_screen(void) {
    /* bg2: "POKéMON" logo, 256 colours, affine */
    lz_to("build/assets/graphics/title_screen/pokemon_logo.png.8bpp.lz", BG_CHAR_ADDR(0));
    lz_to("build/assets/graphics/title_screen/pokemon_logo.bin.lz", BG_SCREEN_ADDR(9));
    /* bg0: Rayquaza; bg1: clouds */
    lz_to("build/assets/graphics/title_screen/rayquaza.png.4bpp.lz", BG_CHAR_ADDR(2));
    lz_to("build/assets/graphics/title_screen/rayquaza.bin.lz", BG_SCREEN_ADDR(26));
    lz_to("build/assets/graphics/title_screen/clouds.png.4bpp.lz", BG_CHAR_ADDR(3));
    lz_to("build/assets/graphics/title_screen/clouds.bin.lz", BG_SCREEN_ADDR(27));

    /* gTitleScreenBgPalettes = pokemon_logo.gbapal + rayquaza_and_clouds.gbapal */
    size_t n1, n2;
    u8 *p1 = load_file("graphics/title_screen/pokemon_logo.gbapal", &n1);
    u8 *p2 = load_file("graphics/title_screen/rayquaza_and_clouds.gbapal", &n2);
    u8 pal[15 * PLTT_SIZE_4BPP] = { 0 };
    memcpy(pal, p1, n1 < sizeof pal ? n1 : sizeof pal);
    if (n1 < sizeof pal) memcpy(pal + n1, p2, n2 < sizeof pal - n1 ? n2 : sizeof pal - n1);
    memcpy((void *)BG_PLTT, pal, sizeof pal);
    free(p1);
    free(p2);

    REG_BG2X = (u32)(-29 * 256);
    REG_BG2Y = (u32)(-32 * 256);
    REG_BG2PA = 0x100;
    REG_BG2PD = 0x100;
    REG_BG0CNT = BGCNT_PRIORITY(3) | BGCNT_CHARBASE(2) | BGCNT_SCREENBASE(26) | BGCNT_16COLOR | BGCNT_TXT256x256;
    REG_BG1CNT = BGCNT_PRIORITY(2) | BGCNT_CHARBASE(3) | BGCNT_SCREENBASE(27) | BGCNT_16COLOR | BGCNT_TXT256x256;
    REG_BG2CNT = BGCNT_PRIORITY(1) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(9) | BGCNT_256COLOR | BGCNT_AFF256x256;
    REG_BLDCNT = BLDCNT_TGT1_BG1 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG0 | BLDCNT_TGT2_BD;
    REG_BLDALPHA = BLDALPHA_BLEND(6, 15);
    REG_DISPCNT = DISPCNT_MODE_1 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG0_ON | DISPCNT_BG1_ON | DISPCNT_BG2_ON | DISPCNT_OBJ_ON;
}

int main(int argc, char **argv) {
    const char *shot = NULL;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--root") && i + 1 < argc) snprintf(s_root, sizeof s_root, "%s", argv[++i]);
        else if (!strcmp(argv[i], "--shot") && i + 1 < argc) shot = argv[++i];
    }
    if (!pc_hw_init()) return 1;
    setup_title_screen();

    static uint32_t frame[DISPLAY_WIDTH * DISPLAY_HEIGHT];
    pc_gpu_render_frame(frame);

    if (shot) {
        SDL_Surface *s = SDL_CreateRGBSurfaceWithFormatFrom(frame, DISPLAY_WIDTH, DISPLAY_HEIGHT, 32,
                                                            DISPLAY_WIDTH * 4, SDL_PIXELFORMAT_ARGB8888);
        if (!s || SDL_SaveBMP(s, shot) != 0) pc_fatal("cannot save %s: %s", shot, SDL_GetError());
        SDL_FreeSurface(s);
        pc_log("saved %s", shot);
        return 0;
    }

    if (SDL_Init(SDL_INIT_VIDEO) != 0) pc_fatal("SDL_Init: %s", SDL_GetError());
    SDL_Window *win = SDL_CreateWindow("pokeemerald PC - M1", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                       DISPLAY_WIDTH * 3, DISPLAY_HEIGHT * 3, SDL_WINDOW_RESIZABLE);
    SDL_Renderer *ren = SDL_CreateRenderer(win, -1, SDL_RENDERER_PRESENTVSYNC);
    SDL_RenderSetLogicalSize(ren, DISPLAY_WIDTH, DISPLAY_HEIGHT);
    SDL_Texture *tex = SDL_CreateTexture(ren, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING,
                                         DISPLAY_WIDTH, DISPLAY_HEIGHT);
    int scroll = 0;
    for (int run = 1; run;) {
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT || (e.type == SDL_KEYDOWN && e.key.keysym.sym == SDLK_ESCAPE)) run = 0;
        }
        REG_BG1HOFS = (u16)(scroll++ / 2);    /* drifting clouds, as in the game */
        pc_gpu_render_frame(frame);
        SDL_UpdateTexture(tex, NULL, frame, DISPLAY_WIDTH * 4);
        SDL_RenderClear(ren);
        SDL_RenderCopy(ren, tex, NULL, NULL);
        SDL_RenderPresent(ren);
    }
    SDL_Quit();
    return 0;
}
